window.CAPTIONS = {"congrats": [[0.02, 1.54, "The season may be over,"], [1.54, 4.9, "but the game of life and leadership never ends."], [5.02, 9.62, "You've done the work and you've earned this moment."], [9.62, 11.94, "It's time to celebrate."], [11.94, 15.34, "Welcome to the Athleader Hall of Fame."], [15.34, 17.22, "You have everything you need."], [17.22, 18.9, "You've got this."], [18.9, 21.42, "Now, make it happen."]], "drill_l1": [[0.0, 6.0, "You're mid-task, focused and in rhythm. Your inbox is full,"], [6.0, 9.8, "but you are on track with your to-do list,"], [9.8, 11.9, "and in the background someone is waiting on you."], [11.9, 16.3, "Then suddenly, something you were counting on just fell through."], [17.2, 21.5, "Before you do anything, what is the first thing you notice?"], [21.5, 25.5, "In your body? In your thoughts? What feelings do you have?"], [25.5, 28.3, "Do you have an urge to do something?"], [34.3, 39.5, "There's no right answer to what you just noticed."], [39.5, 41.4, "Don't change it. Just catch it."], [41.4, 46.5, "What you noticed is data. The signal your system sends when the unexpected happens,"], [46.5, 50.4, "before you've decided to do anything."], [51.0, 57.1, "For the rest of the season, every time something falls through, try to catch that signal before you act on it."], [57.1, 65.5, "There is nothing to fix yet. Just become aware."]], "drill_l2": [[0.0, 5.8, "You've been working intently on a critical project for a while now."], [5.8, 10.3, "It's organized, thoughtful, and strategically aligned."], [10.3, 14.2, "People are counting on the current version."], [14.2, 17.6, "However, you just got news."], [17.6, 19.9, "The plans have changed."], [19.9, 27.4, "What you built for the last few months is no longer the priority."], [27.4, 33.6, "Before you respond, what do you notice? In your body, in your thoughts,"], [33.6, 37.4, "your feelings, and your urge to act?"], [48.5, 51.9, "Whatever you're noticing isn't wrong."], [51.9, 55.8, "It's your system's opening move under change."], [55.8, 60.0, "The conditioning is choosing your next move on purpose,"], [60.0, 64.2, "instead of letting your immediate instinct choose for you."], [65.1, 69.2, "A. Push back and defend the original plan."], [69.25, 74.75, "B. Quietly absorb it and adjust on your own."], [74.85, 79.75, "C. Go straight to the people affected and rebuild together."], [79.85, 84.0, "D. Pause and ask questions before reacting."], [89.2, 95.0, "Same pressure one more time, but try the option you didn't pick."], [104.05, 107.8, "You just practiced the option that isn't automatic yet."], [108.3, 112.9, "That's what conditioning feels like before the moment demands it."]], "drill_l3": [[0.36, 3.16, "You have to make an important decision."], [3.16, 9.76, "Four pieces of new information arrive, one at a time, then nothing more comes."], [16.6, 21.5, "This is all the information you're going to get, and the decision is due now."], [21.5, 23.9, "What do you notice right away?"], [23.9, 28.0, "The pull to wait, the urge to move, something else?"], [44.7, 49.8, "How much certainty do you need before you're willing to move?"], [49.8, 52.6, "Most people never test that level."], [52.6, 56.4, "You're about to find out what yours is."], [56.4, 58.5, "Here are your options."], [58.5, 61.1, "Act with what you know."], [61.1, 66.1, "Ask for one more missing input that matters most."], [66.1, 68.9, "Push the decision to someone else."], [68.9, 70.9, "Wait for more certainty."], [86.3, 93.5, "Now, new decision, same amount of information as before, four pieces of six."], [93.5, 95.5, "What do you do this time?"], [106.6, 112.4, "You just tested your comfort zone and change in one sitting."], [112.4, 118.2, "This week, notice one real decision where you're waiting for more certainty than you actually need,"], [118.2, 123.6, "and practice taking action with incomplete information."]], "drill_l4": [[0.45, 3.73, "Something didn't go the way you hoped for."], [3.73, 8.0, "To keep it real, it didn't work."], [8.0, 13.45, "You have something else that needs your full attention, and it's in 15 minutes."], [13.45, 19.1, "Before you decide what to do next, what is still with you from what just happened?"], [19.1, 21.3, "Name it, even if briefly."], [36.45, 41.9, "How long does the last moment control the next one?"], [41.9, 44.3, "That's reset speed."], [44.3, 49.3, "And like an athlete's recovery between reps, it can be conditioned."], [49.3, 51.25, "Here are your options."], [51.25, 54.2, "Delay or cancel what's next."], [54.2, 57.4, "Show up and act like nothing happened."], [57.4, 61.1, "Show up, name it briefly and move forward."], [61.1, 64.8, "Show up and let the frustration spill into it."], [75.8, 80.7, "One more thing just went wrong, right on top of this."], [80.7, 82.05, "What do you do now?"], [87.95, 89.7, "Time yourself this week."], [89.7, 98.7, "Take note: after something goes wrong, how long before you're fully present for the next thing on your plate?"], [98.7, 102.7, "Try to shorten the gap."]], "drill_l5": [[0.45, 3.95, "You've made the call."], [3.95, 9.3, "Someone you respect disagrees, strongly, and they're challenging your decision in front of other people."], [9.3, 12.7, "Before you respond, what do you notice?"], [13.2, 18.05, "In your body, your thoughts, your feelings. What is your urge?"], [26.0, 31.05, "Pressure changes when another person is involved."], [31.05, 33.85, "What is your first move? Options could be:"], [33.85, 36.2, "Defend the decision."], [36.2, 39.0, "Back away from your position."], [39.0, 43.4, "Ask them to explain what you're missing."], [43.4, 47.85, "Pause, and separate the disagreement from the person."], [55.65, 60.9, "Now, same disagreement. This time, respond without defending yourself"], [60.9, 63.75, "or abandoning your position."], [67.9, 73.9, "That's hard. And now you're conditioning alignment without commitment."], [74.15, 79.65, "This week, notice one moment when disagreement makes you want to defend,"], [79.65, 82.55, "withdraw, or immediately solve."], [82.55, 86.4, "Catch the urge, then choose your response."]], "drill_l6": [[0.0, 3.0, "You're in the middle of something that matters to you,"], [3.5, 8.0, "something you've been building towards across this whole experience."], [8.8, 11.2, "The plan just changed."], [11.9, 13.8, "You don't have the full picture just yet,"], [14.5, 17.3, "but the last thing you tried didn't work."], [17.9, 21.6, "A person you trust strongly disagrees with your call,"], [21.6, 25.4, "and you already have more on your plate than you know what to do with."], [25.9, 29.4, "And people are watching how you handle this."], [30.0, 33.4, "Before you rush to respond to any of it,"], [34.0, 36.6, "what do you notice right now?"], [47.1, 51.0, "This is what makes the real moments different."], [51.0, 54.8, "Pressure rarely arrives one variable at a time."], [54.8, 58.8, "For five lessons, you've practiced these pressures one at a time."], [58.8, 61.0, "Now they're happening together. Which one is pulling hardest on you?"], [61.0, 65.1, "It's not a verdict. It's the exact information this whole experience was built to surface."], [65.7, 67.0, "What do you think first?"], [67.6, 68.5, "How do you feel?"], [69.1, 70.2, "What do you decide?"], [70.9, 76.3, "How do you access your best decision in the moment of pressure and change?"], [88.3, 91.2, "While you're still responding,"], [91.2, 94.4, "one more piece of information changes things yet again."], [100.8, 105.6, "Six lessons ago, we asked you to notice your first response."], [106.4, 110.4, "Since then, you've practiced changing plans, moving with uncertainty,"], [110.4, 114.2, "recovering after a miss, and staying open in disagreements."], [114.7, 119.4, "That's the difference between knowing what good leadership looks like"], [119.4, 124.1, "and being able to access it when the conditions get hard."], [124.7, 127.1, "You've practiced the latter."]], "m1_1": [[0.0, 6.72, "Welcome, I'm Melissa Dawn Simkins and I am"], [6.72, 14.08, "honored to be your coach through this flagship"], [14.08, 19.56, "experience called the M.V.P. Accelerator Manager Track."], [19.56, 22.64, "Now you're embarking on a dual journey."], [22.64, 26.614, "While your direct report is digging deep into their own potential,"], [26.614, 28.24, "you will be right alongside"], [28.24, 38.24, "them, not just as a supervisor, but as a high-performance Player-Coach."], [38.24, 40.877, "You've officially entered the M.V.P."], [40.877, 44.76, "Accelerator Manager Track in the Athleadership Arena."], [44.76, 47.886, "Now, Athleadership is where elite athletic"], [47.886, 51.16, "mindset meets next-level leadership, mastery"], [51.16, 57.9, "to fuel resilience, unlock purpose, and drive lasting performance."], [57.9, 60.675, "The Athleadership Performance System is our"], [60.675, 63.58, "comprehensive measurement analytics framework"], [63.58, 68.354, "that tracks leadership transformation across the A.R.A.W."], [68.354, 71.62, "dimensions we call Agility, Resilience,"], [71.62, 74.94, "Alignment, and Wellbeing."], [74.94, 77.58, "We also call this the Core 4."], [77.58, 82.34, "Now, it's backed by neuroscience and performance psychology."], [82.34, 86.92, "It is the science and the soul of our model."], [86.92, 91.72, "To ensure we're all aligned, let's clarify our key terms."], [91.72, 97.92, "You'll hear me refer to your direct report as the player or the Athleader."], [97.92, 101.18, "An Athleader is anyone committed to conditioning"], [101.18, 104.44, "their leadership with the discipline and mindset"], [104.44, 111.5, "of an elite athlete to fuel resilience, unlock purpose, and sustain performance."], [111.5, 114.255, "And if you've never seen yourself as an athlete,"], [114.255, 116.78, "or if your direct report hasn't either, it's"], [116.78, 118.14, "OK."], [118.14, 121.44, "This isn't about playing sports or lifting weights."], [121.44, 124.929, "It's about unlocking the discipline, the mindset,"], [124.929, 127.92, "and the clarity and inner strength already"], [127.92, 131.0, "in you to win from within."], [131.0, 132.653, "You are the Player-Coach,"], [132.653, 136.82, "participating in your own leadership development while actively"], [136.82, 138.8, "coaching your player."], [138.8, 141.818, "Our goal is to give you practical frameworks to"], [141.818, 144.9, "make your coaching conversations more impactful,"], [144.9, 150.16, "your team more aligned, and your own leadership more sustainable."], [150.16, 153.387, "Before we begin, I want to ask you to reflect on"], [153.387, 156.48, "one leadership behavior you want to strengthen"], [156.48, 158.24, "for yourself."], [158.24, 161.933, "What is one leadership behavior you want to improve"], [161.933, 165.12, "for how you support your team's performance?"], [165.12, 168.44, "Keep this front and center as we go through"], [168.44, 171.76, "this journey and build your own 90-day plan"], [171.76, 174.16, "over the course of this experience."], [174.16, 178.54, "We'll come back at the end and celebrate your progress."], [178.54, 179.737, "In our next video,"], [179.737, 184.66, "we'll begin your conditioning by focusing on the most important person you"], [184.66, 186.58, "lead, yourself."]], "m1_2": [[0.0, 3.652, "Welcome back. Let's start with a question."], [3.652, 7.913, "How often do you feel like you're simply reacting"], [7.913, 12.0, "to change rather than truly leading through it?"], [12.0, 19.0, "This brings us to a critical focus area, leading yourself through change."], [19.0, 22.457, "This isn't just about managing shifting timelines."], [22.457, 26.261, "It's about intentionally managing your own inner state,"], [26.261, 32.0, "your energy, your focus and stability so you can become the anchor your team needs."], [32.0, 36.477, "In the Athleadership framework, your wellbeing is not a luxury."], [36.477, 38.822, "It's a competitive advantage that"], [38.822, 42.305, "fuels your resilience and agility under pressure."], [42.305, 46.0, "It's the foundation of sustainable high performance."], [46.0, 50.038, "I'll give you an example from my own life. A few years back,"], [50.038, 53.875, "I was trying to do it all. You know what that looks like."], [53.875, 55.154, "Running a business,"], [55.154, 60.0, "caring for my family and ending up physically and emotionally exhausted."], [60.0, 63.862, "But my team really felt that. My family felt it."], [63.862, 67.0, "I wasn't leading. I was just surviving."], [68.0, 73.427, "It was only when I made my own wellbeing a non-negotiable and protected my"], [73.427, 79.0, "time and recovery that I was able to lead effectively through changes again."], [79.0, 83.434, "Now it's your turn. In your playbook, you'll find a drill for this."], [83.434, 88.0, "Your action is to define what you want to get out of this experience."], [88.0, 92.963, "By identifying one specific pressure point you're feeling right now"], [92.963, 98.0, "and one wellbeing practice you can implement this week to manage it."], [98.0, 102.467, "And here's your challenge. Look at your calendar for the next week."], [102.467, 106.0, "Does your schedule reflect what you say is important?"], [106.0, 109.615, "If not, what's one small change you can make to"], [109.615, 113.0, "better align your time with your intentions?"], [113.0, 113.984, "And remember,"], [113.984, 119.357, "part of that alignment is protecting the time for your own development."], [119.357, 123.822, "Make sure you block time on your calendar for this journey."], [123.822, 127.0, "It's a non-negotiable. Invest in yourself."], [127.0, 132.034, "Once you've done that, I'll see you in the next video where we'll explore"], [132.034, 137.0, "how this focus on self-leadership turns into a multiplier for your team."]], "m1_3": [[0.84, 2.0, "Welcome back."], [2.0, 4.24, "Have you ever considered that your primary role"], [4.24, 8.32, "isn't just to manage work, but it's to multiply talent?"], [8.32, 11.64, "We call this the manager multiplier effect."], [11.64, 13.5, "The idea is very simple."], [13.5, 15.66, "Your leadership is a catalyst."], [15.66, 19.14, "Your actions, your coaching, your alignment,"], [19.14, 23.58, "don't just add to your team's output, they multiply it."], [23.58, 26.5, "When you effectively coach one player,"], [26.5, 29.62, "their increased performance and engagement and alignment"], [29.62, 34.62, "lifts the entire team and drives measurable business results."], [34.9, 36.5, "You're not on the sidelines."], [36.5, 38.66, "You're driving how your direct report"], [38.66, 43.66, "and your broader team applies M.V.P. in real time."], [43.74, 46.38, "I saw this with a manager named David."], [46.38, 49.72, "He invested the time in coaching his player, Kim,"], [49.72, 51.98, "on her presentation skills."], [51.98, 55.14, "Now, Kim then led a high stakes client pitch"], [55.14, 56.82, "that her team won."], [56.82, 58.9, "The winning boosted the team morale,"], [58.9, 60.7, "secured a major contract,"], [60.7, 64.82, "and got the whole team recognized by senior leadership."], [64.82, 68.5, "David's one coaching investment was multiplied"], [68.5, 72.04, "into a team win and a business win."], [73.02, 76.5, "Your play is to identify one area"], [76.5, 79.86, "where your player's growth could have a multiplier effect"], [79.86, 81.42, "on the team."], [81.42, 83.74, "Is it their technical skills?"], [83.74, 85.94, "Maybe their ability to collaborate?"], [85.94, 87.64, "Note this in your playbook."], [87.64, 92.1, "This becomes a strategic focus for your coaching."], [92.1, 95.48, "Think about your team's biggest goal for this quarter."], [95.48, 99.46, "How could you align stakeholders outside of your immediate team"], [99.46, 102.04, "to align on shared goals and execution?"], [103.08, 106.4, "Have you translated direction from your senior leaders"], [106.4, 110.52, "into clear, actionable steps for your team?"], [110.52, 113.8, "How can your player's development in this program"], [113.8, 117.0, "directly contribute to achieving that goal?"], [117.0, 119.16, "Could this insight to your direct report"], [119.16, 122.16, "create greater alignment through the 90-day plan?"], [122.16, 123.92, "Let's be specific."], [123.92, 126.2, "Use the multiplier effect."], [126.2, 129.56, "Drill in your playbook to capture your thoughts"], [129.56, 131.3, "on these questions."], [131.3, 134.28, "In our next segment, we'll get tactical"], [134.28, 137.64, "about how to set the stage for this kind of impact"], [137.64, 138.92, "with your player."]], "m1_4": [[0.8, 2.28, "Hi there, welcome back."], [2.28, 4.56, "The first conversation you have with your player"], [4.56, 8.78, "can set the trajectory for the entire program."], [8.78, 11.04, "How do you make it count?"], [11.04, 15.12, "The goal is to establish a clear and committed partnership"], [15.12, 19.68, "from day one in what we call the commitment meeting."], [19.68, 21.28, "Now this isn't a typical check-in,"], [21.28, 25.2, "it's a dedicated session to align on expectations,"], [25.2, 28.72, "define success and agree on support."], [28.72, 30.96, "Too often, development programs fail"], [30.96, 34.24, "because of misalignment in expectations."], [34.24, 37.34, "This meeting prevents that and is the first step"], [37.34, 40.96, "in activating the manager multiplier effect."], [40.96, 45.76, "And finally, this meeting empowers you to agree on support."], [45.76, 48.64, "This is a two-way street first."], [48.64, 51.62, "Ask your player, what do you need for me"], [51.62, 54.12, "to be successful in this program?"], [54.12, 56.88, "A critical form of support is helping them"], [56.88, 59.48, "make sure they have the time to invest"], [59.48, 61.2, "and they make it a priority."], [61.2, 63.6, "You could offer help with protecting that space"], [63.6, 65.84, "within their work schedule."], [65.84, 69.16, "Then tell them what you need from them,"], [69.16, 74.0, "such as proactively sharing their insights from the course."], [74.0, 78.24, "Your play this week is simple but non-negotiable."], [78.24, 80.4, "Schedule and hold the commitment meeting."], [81.36, 86.16, "Use the agenda in your playbook to guide the conversation."], [86.16, 87.84, "During your commitment meeting,"], [87.84, 91.92, "your player may seem hesitant to share their goals."], [91.92, 95.18, "How do you apply the principles of psychological safety"], [95.18, 99.36, "to encourage them to open up without applying pressure?"], [99.36, 102.86, "Your playbook contains the first conversation guide"], [102.86, 104.96, "with key questions and prompts"], [104.96, 108.14, "to help you navigate this exact scenario."], [108.14, 110.98, "Review it before your meeting to ensure you're prepared"], [110.98, 113.64, "to build that foundation of trust."], [113.64, 116.04, "This concludes lesson one."], [116.92, 119.24, "In our next lesson, we will begin the deep work"], [119.24, 123.14, "of defining your own M.V.P. plus V blueprint."], [123.14, 124.68, "You've got this."], [124.68, 126.56, "Now, make it happen."]], "m2_1": [[0.0, 7.96, "Welcome back."], [7.96, 13.08, "In our last session, you set the stage for a championship season."], [13.08, 16.66, "This week, we get into the data."], [16.66, 17.842, "In elite sports,"], [17.842, 23.38, "teams spend millions on scouting reports because you can't design a winning"], [23.38, 28.26, "game plan without first understanding the talent."], [28.26, 32.56, "In leadership, the best coaches do the same."], [32.56, 38.82, "This lesson is about becoming a student of your talent, but it starts with an honest"], [38.82, 42.5, "scouting report on yourself."], [42.5, 45.98, "This is not about what you've heard before,"], [45.98, 49.54, "but what you condition yourself to do daily."], [49.54, 54.18, "To coach your player, you must first lead yourself."], [54.18, 55.569, "In our next video,"], [55.569, 60.74, "we'll start that process by creating your own leadership blueprint,"], [60.74, 62.9, "your M.V.P. plus V."]], "m2_2": [[0.96, 5.0, "When was the last time you owned your values"], [5.0, 8.88, "and those values were the reason for a great day at work"], [8.88, 10.6, "or a draining one?"], [10.6, 14.08, "Your first move is to get crystal clear"], [14.08, 16.8, "on your own leadership blueprint."], [16.8, 20.04, "We call this your M.V.P. plus V,"], [20.04, 25.0, "your mission, vision, purpose, and values."], [25.0, 29.36, "This is what we call your foundation for forever,"], [29.36, 31.2, "for your entire life."], [31.2, 35.2, "And it directly informs how you lead."], [35.2, 38.76, "Let's quickly define the terms so you can have clarity"], [38.76, 41.56, "as you go through your playbook drill."], [41.56, 45.64, "Your purpose is your fundamental why."], [45.64, 49.32, "It's the lasting impact you want to have."], [49.32, 51.96, "Your vision is your where."], [51.96, 54.56, "It's the vivid picture of the future"], [54.56, 56.32, "and what you're creating,"], [56.32, 58.94, "both personally and professionally."], [58.94, 61.46, "And your mission is your how."], [61.46, 65.36, "It's what you do every day to make that vision a reality."], [66.38, 69.3, "When you lead from this place of clarity,"], [69.3, 72.7, "your coaching is an act of alignment."], [72.7, 74.58, "When you're disconnected from it,"], [74.58, 78.76, "you risk misalignment, which can lead to burnout."], [78.76, 81.8, "That internal conflict between what you value"], [81.8, 85.24, "and what you do is massively energy draining."], [86.2, 89.44, "I once coached an executive who was brilliant,"], [89.44, 91.12, "but miserable."], [91.12, 92.4, "After this exercise,"], [92.4, 96.12, "she realized a core value was creativity,"], [96.12, 99.68, "yet her role had become purely administrative."], [99.68, 103.12, "Her work was misaligned with her purpose."], [103.12, 104.8, "Armed with this clarity,"], [104.8, 109.32, "she proposed carving out time for an innovation task force."], [109.32, 110.64, "Her leader agreed,"], [110.64, 113.64, "and her energy and performance skyrocketed"], [113.8, 117.36, "because her work was now fueling her."], [117.36, 121.2, "Now, head to your playbook for drill 2.2."], [121.2, 124.12, "Your play is to complete the M.V.P. audit"], [124.12, 127.26, "to define your own mission, vision, and purpose."], [127.26, 131.66, "Then identify one low value task you can delegate"], [131.66, 135.72, "or diminish this week to better align your M.V.P."], [135.72, 138.16, "and reclaim your energy."], [138.16, 140.16, "Once you've completed that drill,"], [140.16, 141.98, "join me in the next video,"], [142.02, 145.26, "where we'll shift focus from leading self"], [145.26, 148.3, "to leading others by creating a climate"], [148.3, 150.12, "of psychological safety."]], "m2_3": [[0.4, 3.92, "Your player is digging into their own blueprint."], [3.92, 6.68, "How do you coach what you can't see?"], [6.68, 10.6, "This week, your player is on a parallel journey,"], [10.6, 13.42, "creating their own inner blueprint."], [13.42, 16.28, "This is a very vulnerable process."], [16.28, 19.86, "Your role as their coach is not to judge the data"], [19.86, 23.2, "that's uncovered, but to help them find meaning in it"], [23.2, 26.6, "by creating what we call psychological safety."], [26.6, 29.88, "This is the bedrock of lasting growth."], [29.88, 32.16, "It's the feeling that they can share insights"], [32.16, 35.88, "and struggles without fear of judgment."], [35.88, 38.04, "A manager I knew meant well,"], [38.04, 40.72, "but when his employees shared a past failure,"], [40.72, 42.32, "he immediately jumped in with,"], [42.32, 44.42, "well, here's what you should have done."], [45.58, 48.64, "He completely shut down the conversation."], [48.64, 51.12, "A Player-Coach responds differently."], [51.12, 54.52, "They might say, thank you for trusting me with that."], [54.52, 57.4, "What did that experience teach you?"], [57.4, 59.52, "The first response judges."], [59.52, 64.36, "The second invites reflection and demonstrates curiosity."], [64.36, 68.66, "Your playbook this week is to practice creating safety."], [69.52, 72.92, "In your next check-in, ask open-ended,"], [72.92, 75.1, "non-judgmental questions."], [75.1, 78.76, "Questions like, what has been the most surprising insight"], [78.76, 80.56, "from this process?"], [80.56, 83.64, "Now consider this, you notice your player"], [83.64, 86.2, "is only sharing positive updates."], [86.2, 88.36, "How can you gently create an opening"], [88.36, 91.36, "for them to discuss the challenges?"], [91.36, 95.12, "Go into your playbook where coaching for safety drills"], [95.12, 97.9, "are providing prompts to help you reinforce"], [97.9, 99.92, "that this is safe space for growth,"], [99.92, 101.78, "not just performance reporting."], [102.8, 105.3, "In our final segment for this lesson,"], [105.3, 108.04, "we'll build on that trust with a framework"], [108.04, 111.56, "for giving effective forward-looking feedback."]], "m2_4": [[0.84, 4.16, "Welcome to our final segment for lesson two."], [4.16, 7.8, "How do you turn reflection on the past"], [7.8, 10.32, "into fuel for the future?"], [10.32, 12.04, "As your player shares insights,"], [12.04, 15.08, "our goal is to make these conversations"], [15.08, 18.4, "relentlessly forward-looking."], [18.4, 21.4, "We use simple three-step coaching framework"], [21.4, 23.04, "to make that happen."], [23.04, 26.24, "Step one, acknowledge the insight."], [26.24, 29.08, "Before you guide, you must validate."], [29.08, 32.64, "Start by saying, that's a powerful realization."], [33.48, 36.52, "This simple step builds trust."], [37.32, 41.24, "Step number two, connect to the future."], [41.24, 44.24, "This is key and it's pivotal."], [44.24, 46.12, "Connect through learnings to the future"], [46.12, 47.72, "and the future actions."], [47.72, 50.44, "If they identify a strength, ask them,"], [50.44, 52.36, "how can you intentionally use these strengths"], [52.36, 53.96, "to achieve your 90-day goal?"], [54.84, 58.52, "Step three, co-create the future path."], [58.68, 60.92, "Finally, turn insights into commitment."], [60.92, 65.12, "Ask, so what's one small action you could take this week"], [65.12, 67.12, "based on what you've learned?"], [67.12, 69.48, "This builds ownership."], [69.48, 73.24, "Your play is to prepare your next one-on-one."], [73.24, 75.16, "Before the meeting, open your playbook"], [75.16, 77.76, "to the forward-looking framework guide."], [77.76, 80.32, "Use it to script out how you will acknowledge,"], [80.32, 83.2, "connect and co-create with your player."], [83.2, 85.72, "This concludes lesson two."], [85.72, 89.36, "In our next lesson, we will introduce the 90-Day Way,"], [89.36, 91.56, "the operating system you will use"], [91.56, 94.72, "to turn these insights into measurable progress."], [94.72, 96.12, "You've got this."], [96.12, 98.04, "Now, make it happen."]], "m3_1": [[0.0, 7.74, "Welcome back."], [7.74, 9.5, "You've scouted the talent."], [9.5, 11.94, "Now it's time to create the game plan."], [11.94, 16.52, "In sports, a season is won through consistent, structured approach."], [16.52, 19.38, "In leadership, the same is true."], [19.38, 22.54, "That system we call the 90-Day Way."], [22.54, 27.02, "It's our framework for turning intention into measurable impact."], [27.02, 28.506, "In our next segment,"], [28.506, 33.26, "you'll create your own 90-day plan to model the focus you expect"], [33.26, 34.06, "from your team."]], "m3_2": [[0.0, 5.545, "What is the one goal, if you achieved it in the next 90 days,"], [5.545, 10.0, "would fundamentally change your game as a leader?"], [10.0, 14.0, "The 90-Day Way is a time-bound leadership operating system."], [14.0, 15.958, "Before you can guide your team,"], [15.958, 20.0, "before you can create a plan for them, you must create your own."], [20.0, 26.0, "This forces you to get clear on your priorities, identify your own roadblocks,"], [26.0, 30.0, "and model the very focus you expect from your team."], [30.0, 36.0, "A manager I coach felt perpetually behind. Her 90-day goal wasn't about a project."], [36.0, 38.0, "It was about her leadership."], [38.0, 43.707, "Her goal? Delegate one significant responsibility to a high-potential"], [43.707, 49.0, "team member to free up five hours a week for strategic thinking."], [49.0, 53.0, "It was specific, measurable, and transformational."], [53.0, 59.0, "Your play is to use the template in your playbook to draft your own 90-day plan."], [59.0, 63.043, "You'll see it starts with space for your M.V.P."], [63.043, 67.0, "and a quick assessment of your Core 4 pillars."], [67.0, 70.348, "This ensures your goals are grounded in your"], [70.348, 74.0, "purpose and focus on the areas you want to grow."], [74.0, 80.0, "Focus on one single high-impact goal for yourself as a leader."], [80.0, 82.0, "You've set your 90-day goal."], [82.0, 86.125, "Now identify one roadblock, the distraction,"], [86.125, 91.0, "habit, or meeting that is most likely to derail you."], [91.0, 98.0, "And ask yourself, which of your Core 4 pillars will this roadblock test the most?"], [98.0, 104.0, "Is it a test of your resilience, your agility, your alignment, your wellbeing?"], [104.0, 107.0, "Understanding this helps you prepare."], [108.0, 110.0, "What is your plan to neutralize it?"], [110.0, 116.0, "To capture your thinking, turn to the roadblock neutralizer drill in your playbook."], [116.0, 118.362, "Once you have your own plan in place,"], [118.362, 122.0, "we'll focus on how to introduce this system to your team."], [122.0, 124.0, "I'll see you in the next video."]], "m3_3": [[0.0, 5.984, "Welcome back. How do you get your entire team rowing in the same direction,"], [5.984, 7.5, "on the same rhythm,"], [7.5, 10.5, "especially when everything feels like a priority?"], [10.5, 13.92, "The 90-Day Way is not just a personal tool."], [13.92, 17.5, "It's a powerful framework for team alignment."], [17.5, 19.517, "And there's a science to this."], [19.517, 22.542, "Researchers have found that sports teams with"], [22.542, 25.5, "high levels of psychological predictability,"], [25.5, 31.5, "what we can think of as neurological alignment, simply perform better."], [31.5, 36.5, "For leaders, this means alignment isn't just a strategy. It's a rhythm."], [36.5, 40.42, "High-performing teams share a mental cadence that"], [40.42, 44.5, "maps directly to organizational trust and cohesion."], [44.5, 49.5, "I saw a team completely transform when their manager used this."], [49.5, 53.5, "Instead of juggling 10 priorities, she brought them together and asked,"], [53.5, 58.5, "what is the one thing we must achieve this quarter to be successful?"], [58.5, 61.611, "They decided on one critical initiative."], [61.611, 65.5, "Every week, their check-in started with that goal."], [65.5, 68.5, "They were more focused and collaborative."], [68.5, 73.5, "Your play is to introduce this concept in your next team meeting."], [73.5, 75.5, "Don't try to boil the ocean here."], [75.5, 78.922, "Use the framework to facilitate a discussion"], [78.922, 82.5, "and set one shared 90-day goal with your team."], [82.5, 87.5, "You can introduce the 90-Day Way, and a team member expresses skepticism,"], [87.5, 90.5, "seeing that it just is another corporate initiative."], [90.5, 94.5, "How do you address their concern and build buy-in?"], [94.5, 98.5, "Your playbook contains a guide called Coaching Through Skepticism,"], [98.5, 103.5, "with talking points to help you navigate that exact moment."], [103.5, 107.5, "Now that your team has a plan, what happens when they hit an obstacle?"], [107.5, 110.767, "In our final topic, we'll talk about this,"], [110.767, 114.5, "and we'll cover how to coach through roadblocks."], [114.5, 116.5, "See you there."]], "m3_4": [[0.0, 3.96, "Welcome to our final topic for Lesson 3."], [3.96, 11.04, "Your team has a plan, but what happens when they hit the first inevitable roadblock?"], [11.04, 14.52, "Your role as coach isn't to clear the road for your team."], [14.52, 20.28, "It's to help them develop the skills to navigate it for themselves."], [20.28, 23.071, "Coaching through roadblocks is about fostering"], [23.071, 25.68, "resilience and problem-solving, reinforcing"], [25.68, 31.68, "the idea that obstacles are a part of the process, not a sign of failure."], [31.68, 35.48, "A team's 90-day plan was derailed by a budget cut."], [35.48, 38.38, "The manager's first question wasn't, how do we fix this?"], [38.38, 43.0, "It was, okay, this is our new reality given this constraint."], [43.0, 45.6, "What are we still able to accomplish?"], [45.6, 49.44, "What creative solutions does this force us to consider?"], [49.44, 53.8, "This empowered the team to find a new path forward."], [53.8, 59.92, "Your play is to anticipate one potential roadblock for your team's 90-day goal."], [59.92, 61.4, "Write it down."], [61.4, 63.342, "Now formulate one powerful,"], [63.342, 68.16, "open-ended question you can ask to kick-start their problem-solving"], [68.16, 70.84, "if that roadblock appears."], [70.84, 73.359, "A new urgent corporate responsibility drops"], [73.359, 75.76, "in the middle of your team's 90-day plan."], [75.76, 78.45, "How do you use the framework to help the team"], [78.45, 80.96, "adapt with agility without losing momentum"], [80.96, 82.76, "or burning out?"], [82.76, 85.36, "Turn to the agility coaching drill in your"], [85.36, 87.96, "playbook and walk through this scenario to"], [87.96, 90.48, "prepare your response."], [90.48, 92.54, "This concludes Lesson 3."], [92.54, 96.365, "You now have the 90-Day Way as your leadership operating system,"], [96.365, 97.8, "a plan for yourself, and"], [97.8, 101.94, "the tools to align your team and coach them through challenges."], [101.94, 105.123, "In our next lesson, activating your M.V.P."], [105.123, 108.76, "will focus on leading the execution of that plan"], [108.76, 111.28, "under real-world pressure."], [111.28, 112.28, "Well done."], [112.28, 113.28, "You got this."], [113.28, 115.24, "Now make it happen."], [115.24, 117.16, "I'll see you in the next lesson."]], "m4_1": [[0.0, 8.84, "Welcome back."], [8.84, 12.4, "You have your M.V.P. and your 90-day game plan."], [12.4, 17.4, "But a plan is just a piece of paper until it meets reality."], [17.4, 19.92, "Pressure is where leadership is revealed."], [19.92, 24.4, "This week is about activating your M.V.P. when it matters most."], [24.4, 29.34, "When the pressure is on, deadlines are tight, and the stakes are high."], [29.34, 33.78, "In our next segment, we'll start by building your own resilience playbook."]], "m4_2": [[0.96, 4.56, "When you get that late-night email that changes everything,"], [5.2, 10.0, "what is your first instinct reaction? Is it calm or chaos?"], [11.12, 13.897, "Resilience isn't about avoiding stress."], [13.897, 18.24, "It's about how you recover from it. It's a conditioned skill."], [19.2, 22.72, "In fact, recent studies from Stanford show that"], [22.72, 26.24, "real-time resilience can be seen in brain scans"], [26.24, 31.95, "revealing protective mechanisms that activate under extreme pressure."], [31.95, 33.44, "This tells us that"], [33.44, 39.04, "leaders who train their emotional recovery can regulate themselves more effectively"], [39.04, 42.711, "under chronic stress and make clearer decisions."], [42.711, 46.0, "For leaders, this means having a predefined"], [46.0, 50.96, "resilience playbook instead of go-to actions that help you stay grounded."], [51.92, 57.92, "This is a core component of your leadership impact on others because your team takes"], [57.92, 65.04, "their cues directly from you. A CEO I worked with had a simple but powerful play."], [65.68, 67.615, "When faced with a crisis,"], [67.615, 72.8, "his first move is to never call a meeting. It's to take a 10-minute"], [72.8, 75.754, "walk. He says it allows him to separate the"], [75.754, 78.64, "emotion from the data so he can return and"], [78.64, 82.231, "lead from a place of clarity, not reaction."], [82.231, 86.24, "Your play is to define your own resilience play."], [87.12, 93.376, "In your playbook, identify one stress trigger you frequently face."], [93.376, 95.84, "Then write down one simple"], [95.84, 101.492, "immediate action you can take to create a moment of pause before you respond."], [101.492, 102.96, "You're about to give"], [103.04, 105.913, "critical feedback to a sensitive team member"], [105.913, 108.72, "and you feel your own stress levels rising."], [109.6, 112.433, "What is the one move from your resilience"], [112.433, 115.68, "playbook you can use in the five minutes before"], [115.68, 120.855, "the conversation? Turn to the pre-conversation primer in your playbook."], [120.855, 122.24, "It provides a quick"], [122.24, 125.756, "drill to help you center yourself using resilience"], [125.756, 128.64, "plays before any high-stakes interaction."], [129.6, 132.24, "Now that you've prepared yourself to handle pressure,"], [132.24, 138.48, "let's talk about how you coach your team through it. I'll see you in the next video."]], "m4_3": [[0.0, 4.183, "Welcome back! You've announced a change and"], [4.183, 8.56, "you're met with silence or subtle resistance."], [8.56, 9.953, "What's going on?"], [9.953, 16.22, "Resistance to change is rarely about the change itself. It's often about"], [16.22, 20.53, "what people fear they will lose. Certainty,"], [20.53, 24.64, "competency, or connection. An agile coach"], [24.64, 30.52, "doesn't just push their agenda. They first diagnose the root of the resistance. Your"], [30.52, 37.68, "job is to listen for the unspoken fears so you can address them directly."], [37.68, 40.856, "A manager was rolling out a new software and"], [40.856, 43.96, "her team was dragging their feet instead of"], [43.96, 47.25, "pushing harder. She held one-on-ones and asked,"], [47.25, 50.4, "what is the biggest concern for you with this"], [50.4, 56.038, "new system? She discovered they weren't resistant to the software."], [56.038, 58.6, "They were afraid they wouldn't"], [58.6, 65.16, "be able to learn it fast enough and would look incompetent. The problem wasn't the"], [65.16, 68.943, "change. It was fear about losing competence."], [68.943, 72.64, "Your play is to listen for the loss and the"], [72.64, 77.54, "stress points. Think of a recent change you've implemented."], [77.54, 80.28, "What did your team stand to lose?"], [80.28, 82.718, "Certainty, competency, or connection."], [82.718, 85.88, "Where are the stress signals? What steps can you"], [85.88, 89.027, "take to anticipate and mitigate them?"], [89.027, 93.96, "Understanding this will change how you lead. You need your"], [93.96, 97.3, "player to take on a challenge of a new role,"], [97.3, 100.64, "but they seem hesitant. How can you use this"], [100.64, 103.601, "diagnostic lens to uncover their underlying"], [103.601, 106.7, "fear and coach them through it? Your playbook"], [106.7, 110.051, "has a coaching through hesitation guide."], [110.051, 113.82, "Use it to diagnose questions and prepare your"], [113.82, 116.763, "conversation and uncover the root cause."], [116.763, 120.22, "Once you can diagnose resistance, the next step"], [120.22, 124.9, "is to coach for agility. We'll cover that in our final segment."]], "m4_4": [[0.0, 3.48, "Welcome to our final topic in lesson four."], [3.48, 6.84, "How do you coach your player to be more agile"], [6.84, 9.84, "when you can't predict what's gonna happen next?"], [9.84, 11.96, "You don't coach for every scenario,"], [11.96, 14.72, "you coach for a mindset."], [14.72, 16.64, "This isn't just theory."], [16.64, 21.24, "In the sports world, speed, agility, quickness, training"], [21.24, 25.4, "is proven to boost an athlete's neuromuscular response"], [25.4, 27.48, "and decision-making speed."], [27.48, 31.24, "In the business world, the results are just as stark."], [31.24, 35.12, "A recent study found that high-agility organizations"], [35.12, 39.4, "had a 97% revenue growth"], [39.4, 44.4, "compared to just 46% for low-agility ones."], [44.52, 48.0, "Coaching for agility means empowering your player"], [48.0, 50.32, "to see change not as a threat,"], [50.32, 52.68, "but as an opportunity to pivot."], [53.68, 56.2, "Your role is to shift from being"], [56.24, 60.84, "the chief problem solver to the chief question asker,"], [60.84, 64.6, "building their capacity to adapt independently."], [65.68, 68.96, "A player was panicking because a key vendor"], [68.96, 70.84, "for her project pulled out."], [70.84, 74.72, "Her manager's first response wasn't, here's what we'll do."], [74.72, 77.4, "It was, okay, that's a tough break."], [77.4, 81.2, "What does this new constraint make possible?"], [81.2, 85.04, "That single question shifted the player from panic"], [85.04, 87.64, "to creative problem solving."], [87.64, 91.68, "Your play is to add one powerful agility question"], [91.68, 93.68, "to your coaching toolkit."], [93.68, 96.68, "The next time your player comes to you with a problem"], [96.68, 100.24, "or even delay in decision when conditions are in flux,"], [100.24, 102.32, "your first response will be,"], [102.32, 106.08, "what's your initial read on a path forward?"], [106.08, 108.88, "Your player's 90-day goal is suddenly at risk"], [108.88, 110.36, "due to a reorg."], [110.36, 113.04, "They come to you frustrated and ready to give up."], [113.04, 115.04, "How do you use agility coaching"], [115.04, 117.6, "to help them reframe the situation"], [117.6, 120.12, "and find a new way to win?"], [120.12, 122.92, "The agility coaching framework in your playbook"], [122.92, 126.16, "is designed for this exact scenario."], [126.16, 129.24, "Use it to structure a conversation that shifts your player"], [129.24, 132.4, "from frustration to creative problem solving."], [133.48, 135.56, "This completes lesson four."], [135.56, 139.4, "You are now equipped to activate your M.V.P. under pressure"], [139.4, 142.4, "and coach your team with greater agility."], [142.44, 145.28, "In our next lesson, Play the Season,"], [145.28, 148.36, "we will focus on sustaining this momentum"], [148.36, 151.44, "through energy management and course correction."], [151.44, 152.44, "I'll see you there."]], "m5_1": [[0.0, 11.92, "Okay, we're diving deep into the season."], [11.92, 15.12, "This is where fatigue can set in."], [15.12, 20.72, "A championship season isn't won by the team that starts the fastest."], [20.72, 25.32, "It's won by the team that can sustain its performance."], [25.32, 28.839, "This lesson is all about the science of"], [28.839, 33.44, "sustainable high performance for you and your team."], [33.44, 39.1, "In our next video, we'll begin by focusing on the most valuable resource you have as"], [39.1, 41.6, "a leader, your energy."]], "m5_2": [[0.0, 4.72, "Do you manage your time or do you manage your energy?"], [4.72, 7.64, "There's a profound difference."], [7.76, 13.96, "The most effective leaders are masters of energy management."], [13.96, 18.6, "This directly impacts your cognitive performance."], [18.6, 24.32, "Neuroscience shows that physical conditioning through things like aerobic training,"], [24.32, 28.4, "actually boost gray matter and executive function,"], [28.4, 33.68, "improving your focus, emotional regulation and discipline."], [33.68, 36.537, "Your physical wellness is the engine for"], [36.537, 39.68, "your mental clarity and performance stamina."], [39.68, 41.568, "And with that understanding,"], [41.568, 45.68, "they intentionally schedule their days not just around tasks,"], [45.68, 48.24, "but around their energy cycles."], [48.24, 51.2, "This is what separates high performers."], [51.2, 54.019, "I know a female executive who blocks the"], [54.019, 57.12, "first 90 minutes of every day for deep work."], [57.12, 59.6, "No emails, no meetings."], [59.6, 65.2, "She also schedules two 15-minute recovery blocks in the afternoon."], [65.2, 72.0, "By managing her energy, she accomplishes more in six hours than most do in 10."], [72.0, 76.72, "Your play is to conduct a personal energy audit."], [76.72, 83.92, "For one day this week, I want you to track your energy levels, high, medium, low."], [83.92, 90.72, "In your playbook, note what activities drain you and what activities fuel you."], [90.72, 96.48, "You've identified that back-to-back meetings are your biggest energy drain."], [96.48, 100.157, "What is the one specific boundary you can set"], [100.157, 104.16, "next week to protect your energy and performance?"], [104.16, 107.604, "In what ways are you protecting boundaries in your"], [107.604, 111.6, "personal and professional life to create time of recovery?"], [111.6, 116.88, "To put this into practice, turn to the boundary setting drill in your playbook"], [116.88, 120.56, "and commit to one specific action."], [120.56, 122.64, "Once you've audited your energy,"], [122.64, 126.8, "we'll talk about how your habits impact your team's performance."], [126.8, 130.0, "I'll see you in the next video."]], "m5_3": [[0.96, 2.6, "Welcome back."], [2.6, 4.86, "Are you celebrating your team's hard work?"], [4.86, 8.32, "Are you accidentally celebrating a culture of burnout?"], [9.66, 13.2, "As a leader, you are the primary architect"], [13.2, 15.86, "of your team's performance culture."], [15.86, 19.84, "A burnout-proof team isn't one that works less."], [19.84, 24.16, "It's one that works smarter and recovers intentionally."], [24.16, 27.22, "Your most powerful tool is modeling."], [27.22, 29.02, "Your team won't believe it."], [29.02, 32.74, "If it's okay to rest, but you say it is,"], [32.74, 35.04, "but then you work all hours."], [35.04, 38.54, "This is the heart of a manager's multiplier effect."], [38.54, 42.78, "You have the ability to make an impact that ripples."], [42.78, 47.78, "A manager notices his team was sending emails at all hours."], [47.86, 49.86, "In their next team meeting, he said,"], [49.86, 51.46, "I want to be clear,"], [51.46, 55.1, "I do not expect responses outside of work hours."], [55.1, 57.24, "To protect our team's recovery time,"], [57.26, 60.86, "let's all commit to using the schedule send feature"], [60.86, 64.42, "for any emails written after 6 p.m."], [64.42, 68.44, "You see, he modeled it and the culture shifted."], [68.44, 72.7, "Your play is to model one sustainable performance norm"], [72.7, 74.18, "this week."], [74.18, 78.6, "It could be taking a full lunch break away from your desk,"], [78.6, 81.54, "ending a meeting five minutes early"], [81.54, 85.04, "or explicitly signing off at the end of the day."], [86.04, 91.04, "You see, the star player is working constantly."], [91.14, 94.06, "You see them, you're worried about burnout,"], [94.06, 97.32, "but you also don't want to discourage their commitment."], [97.32, 99.46, "How do you initiate a conversation"], [99.46, 101.56, "that praises their dedication"], [101.56, 104.8, "while coaching them on sustainable performance?"], [104.8, 108.2, "Your playbook has a sustainable performance coaching guide"], [108.2, 111.32, "with conversation starters to help you navigate"], [111.32, 115.96, "this important conversation with both praise and care."], [115.96, 118.32, "In our final segment for this lesson,"], [118.32, 122.04, "we will cover how to move from modeling good habits"], [122.04, 126.62, "to strategically facilitating recovery for your entire team."]], "m5_4": [[0.72, 4.32, "Welcome to our final topic in lesson five."], [4.32, 8.04, "Your team just finished a massive project"], [8.04, 11.0, "and everyone is exhausted."], [11.0, 12.2, "What's your next move?"], [13.08, 16.72, "In sports, the post-game recovery protocol"], [16.72, 20.74, "is as important as the pre-game warmup."], [20.74, 23.38, "In business, it should be no different."], [23.38, 27.54, "Facilitating team recovery is the intentional process"], [27.54, 31.38, "of helping your team recharge and reset"], [31.38, 34.18, "after a period of intense effort."], [34.18, 38.02, "It prevents burnout, reinforces the value of their work,"], [38.02, 40.34, "and prepares them for the next challenge."], [41.3, 43.18, "After a grueling quarter end,"], [43.18, 45.06, "a manager didn't immediately launch"], [45.06, 47.14, "into planning for the next quarter."], [47.14, 50.46, "She dedicated the first team meeting of the new quarter"], [50.46, 54.08, "entirely to retrospective and recovery."], [55.04, 58.84, "They celebrated the wins, discussed the lessons learned,"], [58.84, 62.52, "and she gave everyone an extra half a day to recharge."], [62.52, 66.48, "The team came back energized and focused."], [66.48, 69.78, "At Velvet Suite, we practice the 90-Day Way."], [69.78, 73.3, "And at the end of every quarter, we give a reset day,"], [73.3, 77.44, "which is a half day to focus on a few things."], [77.44, 80.12, "Collective reflection, recharge,"], [80.12, 81.96, "and putting together our thoughts"], [81.96, 86.36, "around what will make the next 90-Day Way even stronger."], [86.36, 89.72, "Your play is to plan a recovery protocol."], [89.72, 92.08, "Look ahead at your team's calendar."], [92.08, 95.16, "After the next big deadline or project launch,"], [95.16, 97.64, "what is the one small thing you can do"], [97.64, 100.74, "to facilitate team recovery?"], [100.74, 102.36, "I want you to schedule it now."], [103.32, 106.32, "Your team is facing a mandatory crunch time"], [106.32, 108.28, "to meet a critical deadline."], [108.28, 110.48, "You can't change the workload,"], [110.56, 113.6, "you can lead their recovery."], [113.6, 117.16, "How do you proactively plan for a post-deadline recovery"], [117.16, 120.78, "to prevent burnout and acknowledge their effort?"], [120.78, 123.2, "Turn to the team's recovery protocols drill"], [123.2, 124.44, "in your playbook."], [124.44, 126.6, "It provides a template for planning"], [126.6, 129.04, "a post-crunch recovery strategy"], [129.04, 133.38, "that rebuilds energy and reinforces trust."], [133.38, 136.24, "This concludes lesson five."], [136.24, 138.88, "You are now equipped with strategies"], [138.88, 142.28, "to manage your own energy and to lead your team"], [142.28, 145.04, "in a way that ensures sustainability,"], [145.04, 149.36, "long-term performance, and health and vitality."], [149.36, 153.6, "And our final lesson will focus on the victory lap,"], [153.6, 156.26, "integrating your learnings and plannings"], [156.26, 158.24, "for your next season of leadership."], [158.24, 159.32, "I'll see you there."], [159.32, 160.98, "You"]], "m6_1": [[0.0, 9.079, "Welcome to the final lesson. You have done the work."], [9.079, 14.84, "You've coached, you've reflected,"], [14.84, 18.137, "and you've grown. This isn't just an ending."], [18.137, 21.36, "It's a commencement. It's about celebrating"], [21.36, 24.493, "the progress you and your player have made,"], [24.493, 27.48, "and intentionally planning for what comes"], [27.48, 29.498, "next. In our first segment,"], [29.498, 34.28, "we'll focus on how to make the new habits you've built permanent"], [34.28, 37.4, "and make them a part of your leadership operating system."]], "m6_2": [[0.66, 2.88, "What is the single most important lesson"], [2.88, 4.8, "you've learned about yourself"], [4.8, 6.37, "as a leader?"], [6.37, 8.11, "The goal of this experience"], [8.11, 11.15, "was never just to learn new concepts."], [11.15, 14.07, "It was to build new habits."], [14.07, 16.67, "The final step in leading yourself"], [16.67, 20.35, "is to consciously decide which of these new behaviors"], [20.35, 24.51, "you want to hardwire into your leadership identity,"], [24.51, 27.13, "moving from a temporary practice"], [27.13, 30.25, "to a permanent part of your operating system."], [31.29, 33.45, "After going through this experience,"], [33.45, 37.85, "a manager realized that his habit of drive-by feedback"], [37.85, 39.97, "was causing anxiety."], [39.97, 42.37, "His new hardwired habit"], [42.37, 46.09, "became scheduling brief intentional feedback sessions."], [46.09, 49.41, "He put it on his calendar every Friday."], [49.41, 52.15, "It became a part of his system."], [52.15, 55.13, "Your play is to look through your playbook,"], [55.13, 57.57, "identify the one new practice"], [57.57, 60.37, "that has been most impactful for you."], [60.37, 63.93, "Now, schedule a reoccurring block on your calendar"], [63.93, 68.01, "to ensure it continues to stay in practice."], [68.01, 71.25, "In three months, the newness of this experience"], [71.25, 72.81, "will have worn off."], [72.81, 75.85, "What is one system or accountability check"], [75.85, 78.39, "you can put into place now"], [78.39, 82.21, "to ensure you don't revert to old leadership habits?"], [82.25, 86.29, "Turn to the hardwire your habits drill in your playbook"], [86.29, 88.05, "to document your commitment"], [88.05, 91.03, "and set your new accountability system."], [92.01, 94.65, "Now that you've cemented your own habits,"], [94.65, 98.17, "let's focus on celebrating your player success."], [98.17, 99.97, "I'll see you in the next video."]], "m6_3": [[0.0, 3.0, "Your player has crossed the finish line."], [3.0, 10.0, "How do you make sure their hard-earned win gets the recognition it deserves?"], [10.0, 17.0, "Your final act as a Player-Coach is to facilitate the championship conversation."], [17.0, 21.0, "And the first part of it is about amplifying their success."], [21.0, 24.0, "This has two parts."], [24.0, 28.0, "Celebrate publicly to reinforce the value of development"], [28.0, 33.0, "and provide visibility to act as their sponsor and advocate."], [33.0, 39.0, "A manager sent a team-wide email celebrating her player's completion of the program"], [39.0, 44.0, "and highlighting a specific project where she applied her new skills."], [44.0, 49.0, "Then she scheduled a 15-minute coffee with her own boss and the player"], [49.0, 55.0, "simply to say, I want you to hear about the great work Sarah is doing."], [55.0, 58.0, "That visibility is priceless."], [58.0, 60.0, "Your play is twofold."], [60.0, 65.0, "First, use the template in your playbook to send a recognition note."], [65.0, 71.0, "Second, identify one senior leader who should hear about your player's success"], [71.0, 74.0, "and plan how you'll create that connection."], [74.0, 77.0, "Your player is humble and uncomfortable with public praise."], [77.0, 80.0, "How do you celebrate their success in a way"], [80.0, 83.0, "that feels authentic and respectful to them"], [83.0, 86.0, "while still providing the visibility they've earned?"], [86.0, 91.0, "It's an opportunity to learn how they like to be recognized and rewarded."], [91.0, 95.0, "For some, it's a public praise. For others, it's private acknowledgement."], [95.0, 99.0, "While others prefer financial recognition or new opportunities."], [99.0, 101.935, "Through understanding more about your player's M.V.P.,"], [101.935, 104.0, "you can build an authentic connection."], [104.0, 109.0, "The Authentic Recognition Guide in your playbook offers strategies"], [109.0, 113.0, "for tailoring your celebration to your player style."], [113.0, 118.0, "In our final segment, we'll discuss how to frame this victory"], [118.0, 122.0, "as the beginning of their next season of growth."]], "m6_4": [[0.0, 4.52, "Welcome to our final video of this experience."], [4.52, 9.92, "The M.V.P. Accelerator is over, but is there development?"], [9.92, 15.52, "The most powerful message you can send is that development is a continuous journey,"], [15.52, 17.24, "not a one-time event."], [17.24, 23.08, "The final part of the championship conversation is to plan the next season."], [23.08, 26.96, "This solidifies the manager's multiplier effect by"], [26.96, 31.52, "embedding a culture of continuous growth on your team."], [31.52, 35.84, "At the end of their final check-in, a coach simply asks,"], [35.84, 37.52, "this was a great season."], [37.52, 41.4, "Based on everything you've learned, what's your primary focus for"], [41.4, 43.76, "the next 90-day season?"], [43.76, 48.36, "This question immediately frames their accomplishments as a foundation for"], [48.36, 52.24, "future growth, not a final destination."], [52.28, 57.32, "Your play is to end your final conversation with that exact question."], [57.32, 60.48, "What's the focus for your next 90 days?"], [60.48, 63.2, "Capture their answers in your playbook."], [63.2, 68.12, "This becomes a starting point for your ongoing coaching relationship."], [68.12, 70.72, "The ultimate challenge is this."], [70.72, 75.36, "How will you take the frameworks from this program, the M.V.P. focus,"], [75.36, 79.2, "the 90-Day Way, the coaching for agility, and"], [79.24, 83.76, "embed them into everyday culture on your team?"], [83.76, 85.04, "What is your first move?"], [86.24, 89.72, "Now, go back to where we began this journey."], [89.72, 95.6, "Reflect upon the one leadership behavior you wanted to strengthen for yourself."], [95.6, 97.56, "How have you made progress?"], [97.56, 101.64, "And the one leadership behavior you wanted to improve for your team."], [101.64, 102.96, "How did you see progress and"], [102.96, 105.72, "where did your 90-day plan support this journey?"], [106.68, 111.16, "As you move forward, I want you to think about this question."], [111.16, 115.64, "Who will benefit from the leader you have become?"], [115.64, 119.72, "Your M.V.P. isn't just a blueprint for your own success."], [119.72, 124.64, "It's a blueprint for the impact you will have on the world."], [124.64, 129.64, "You are leaving a legacy and making an impact that other leaders will follow."], [129.64, 134.32, "You have the opportunity now to put your name on the wall of fame and"], [134.36, 136.48, "share your own story."], [136.48, 139.84, "This is how you inspire others through your journey."], [139.84, 142.44, "We look forward to celebrating your success."], [143.84, 146.16, "Thank you for your commitment."], [146.16, 149.72, "You carry the weight of the workplace in many ways."], [149.72, 155.12, "However, I am so proud of your commitment to your own leadership journey"], [155.12, 158.12, "that fuels the impact you have made on those you lead."], [159.08, 164.08, "Leading from the inside out is where purpose meets performance."], [164.08, 168.04, "The work you do as a coach matters more than you know."], [168.04, 173.08, "It doesn't just build better employees, it builds better leaders."], [173.08, 177.2, "And better leaders build a better world."], [177.2, 179.08, "Keep going."], [179.08, 180.64, "You've got this."], [180.64, 182.56, "Now make it happen."]], "pro_lachina": [[0.0, 14.18, "Hello, my name is Lachina Robinson and I'm a sports broadcaster for ESPN."], [14.18, 20.7, "I am so excited to be joining Melissa Dawn-Simkins and the Velvet Suite as a founding ambassador"], [20.7, 22.9, "for athleadership."], [22.9, 27.5, "You're probably wondering what a basketball analyst has in common with business leaders."], [28.2, 34.1, "When I say the word agility, I hope that resonates with you because it definitely resonates with"], [34.1, 36.74, "me and I will tell you how."], [36.74, 41.14, "As a basketball analyst, it is my job to be the expert on the broadcast."], [41.14, 47.02, "Leading up to a game, I spend countless hours watching film, interviewing players and coaches,"], [47.02, 52.62, "studying statistics, diving into the rules of the game, learning every aspect of the"], [52.62, 54.94, "entire event."], [54.94, 60.98, "My specific function as the color on the broadcast is to explain and analyze why things"], [60.98, 62.58, "are happening."], [62.58, 65.88, "Why does player A have 30 points?"], [65.88, 68.94, "Why is team B in a zone defense?"], [68.94, 72.2, "Why did coach A just call a timeout?"], [72.2, 75.46, "What does it mean when the officials call travel?"], [75.46, 81.18, "I am teaching by taking the viewer behind the veil into the minds of the players, coaches,"], [81.18, 87.26, "officials, even the fans, to explain why certain events are taking place and hopefully"], [87.26, 90.28, "make the game more enjoyable."], [90.28, 95.9, "The definition of agility is the ability to think and understand quickly."], [95.9, 101.14, "There are hundreds of thousands and sometimes millions of people watching a sporting event"], [101.14, 103.9, "on television at any given time."], [103.9, 109.86, "And it's my job to understand what is happening very quickly and to be able to communicate"], [109.86, 114.06, "that to the audience in the moment as it's happening."], [114.06, 119.42, "Talk about pressure, but you get it because it is essential that you are equipped with"], [119.42, 121.86, "this tool as a business leader."], [121.86, 127.46, "Let me give you an example of how agility comes into play in my day to day."], [127.46, 132.66, "In that high pressure situation with millions of viewers watching a game, I have prepared"], [132.66, 136.26, "for what I expect to happen in the game."], [137.26, 142.9, "Sure, nothing in sports ever happens the way we expect, but that doesn't change my role."], [142.9, 145.14, "And that is where agility comes in."], [145.14, 151.94, "As a leader, we can prepare for the moment and do the diligence required to be an expert,"], [151.94, 157.74, "but nothing can prepare you for the moment of having to change course under pressure."], [157.74, 163.22, "To communicate to an audience, to your staff, to those who follow your command that something"], [163.22, 171.26, "else is happening, something I didn't specifically prepare for, but I couldn't predict it."], [171.26, 180.26, "However, because I have trained, I know that I can find my way and make the changes necessary."], [180.26, 185.86, "Agility takes trust that as an expert, you prepared for a change of plans, that the unexpected"], [185.86, 190.66, "outcome or action isn't the end of your skill set or training."], [191.1, 199.18, "You don't know how your opponent will game plan for you, but you know that whatever that"], [199.18, 204.5, "looks like, you can think and understand quickly in order to adjust."], [204.5, 212.1, "You can be agile in reaching your goal, even if you get there in a different way than you expected."], [212.1, 216.38, "Being agile is critical in situations where you need to adjust."], [216.38, 220.12, "I hope this helps you in your journey as an athlete."], [220.12, 223.12, "You have everything you need."], [223.12, 228.4, "You have prepared, practiced, and now it's time to execute."], [228.4, 229.12, "Stay agile."]], "pro_mannino": [[0.0, 13.6, "Hi, everyone. I'm Dr. Michael Manino. There was a moment a few years back when I was leading"], [13.6, 19.92, "a high stakes cross-disciplinary project under a tight deadline with my team. And the stakes"], [19.92, 23.68, "weren't just about the outcome. They were about proving that our team could perform"], [23.68, 28.0, "under pressure. This would be a great example. We'd be setting a great precedent for our"], [28.0, 33.92, "team. We had talented people, but we weren't moving as one. We were working hard in parallel,"], [33.92, 38.96, "but we weren't truly connected. And under pressure, that misalignment starts to compound."], [38.96, 46.24, "Communication gets clipped, trust and psychological safety gets tested, decisions take longer. We"], [46.24, 52.0, "needed to get in sync, literally. Teams on the same wavelength literally performed better."], [52.88, 58.96, "And a study out of Dartmouth actually showed this. Researchers had teams watch silent,"], [58.96, 65.12, "confusing film clips and then discuss what they thought was happening. The most successful teams,"], [65.12, 70.88, "the ones whose brains literally synchronized during the discussions, had one thing in common,"], [70.88, 76.24, "a unique team member who fostered alignment. They weren't the loudest voiced in the room,"], [76.32, 81.92, "but they asked open-ended questions, reflected ideas back, adapted their tone to match the"], [81.92, 86.56, "groups, and they created a safe space for everybody to contribute. That communication"], [86.56, 92.72, "style created deep synchrony, shared understanding and group cohesion. Now, on my own team,"], [92.72, 98.48, "I shifted from pushing for answers to trying to create that space with that communication style."], [98.48, 103.68, "And almost immediately, I saw a shift in people's minds. We realigned on our mission,"], [103.68, 109.12, "clarified priorities, and agreed not just on what we were doing, but how we'd move together."], [109.12, 113.76, "That moment unlocked alignment. People started anticipating each other's needs,"], [113.76, 117.92, "recovering from mistakes instantly, and making faster and better decisions."], [118.88, 124.48, "It felt like team flow. That's an optimal state of consciousness, a collective state of mind where"], [124.48, 129.52, "the whole is greater than the sum of the parts and everything just clicks as if the team operates as"], [129.52, 135.12, "one unified organism with a collective ambition. Everybody's operating at their edge, but in sync."], [136.08, 142.64, "Now, alignment isn't just a one-time event. It's a living, breathing process. Under pressure,"], [142.64, 148.08, "it can fray fast, and agility is what keeps it alive. Alignment gives you direction,"], [148.08, 153.2, "and agility lets you adapt without losing it. And when you have both, you create the conditions for"], [153.2, 159.84, "team flow. The state where trust, communication, and performance all reinforce one another."], [160.72, 166.4, "Now, over the next 90 days, you'll face moments where pressure spikes. That's your cue to pause"], [166.4, 171.52, "and check. Are we still truly aligned? And can we pivot without losing that connection?"], [172.4, 177.04, "So here's my challenge to you. This week, take 20 minutes with your team and ask two questions."], [177.2, 183.36, "What are we really here to accomplish? And how will we move together when things change? How"], [183.36, 188.96, "will we get in sync? Answer honestly, and you'll be building the foundation for alignment, agility,"], [188.96, 191.44, "and team flow. Good luck."]], "pro_ryall": [[0.0, 15.72, "There was a time in my athletic career when my body and my mind hit rock bottom."], [15.72, 19.0, "I had battled a severe eating disorder."], [19.0, 24.76, "I had pushed through multiple burnouts and suffered severe sports injuries."], [24.76, 31.92, "On the outside, it looked like I was winning titles, magazine covers, accolades, traveling"], [31.92, 37.48, "the world with Arnold, but on the inside, I was crumbling."], [37.48, 43.4, "I was performing at an elite level without a foundation that could actually sustain me."], [43.4, 44.4, "You know what?"], [44.4, 49.56, "I didn't even realize how dangerous that was until my body forced me to stop."], [49.56, 52.16, "That was my wake-up call."], [52.16, 57.88, "I learned that resilience and wellbeing, these aren't just side projects."], [57.88, 62.96, "These are the main gain because when you lose your health, nothing else matters."], [62.96, 68.48, "The medals, the money, the milestones, the accolades."], [68.48, 72.88, "For you as leaders, the pressures may look different than mine as a professional athlete"], [72.88, 75.48, "on a competition stage, but they're really not."], [75.48, 77.44, "The demands are the same."], [77.44, 85.56, "Long hours, performance under pressure, high stakes, and the temptation is always there"], [85.56, 89.68, "to sacrifice our own wellbeing for results."], [89.68, 95.52, "The reality is, is peak performance without sustainable wellness, it's always going to"], [95.52, 98.12, "lead to a breaking point."], [98.12, 100.0, "When that happens, it doesn't just affect you."], [100.0, 104.36, "It affects your business, it affects your family, and it affects your legacy."], [105.32, 111.12, "So Wellness IQ, it's about conditioning yourself from the inside out."], [111.12, 115.64, "It's about creating a platform for sustainable wellness so that you can thrive in life and"], [115.64, 123.36, "you can lead with energy, with clarity, and with peace amongst pressure."], [123.36, 128.52, "So if you want to grow as a leader, you have to start by strengthening your foundation"], [128.52, 132.04, "that supports it all, your health and your wellbeing."], [132.08, 137.04, "And an important question I'd love for you to ask yourself is, if I continue at the same"], [137.04, 143.76, "pace I'm moving at now for the next 10 years, is that possible?"], [143.76, 146.68, "Will I still be thriving in 10 years?"], [146.68, 152.92, "And if that answer isn't a confident yes, it's time to do things differently, right?"], [152.92, 159.16, "You get to lead differently, and that starts with you."], [159.16, 167.4, "Because when you show up as your healthiest, most resilient, aligned self, that's where"], [167.4, 172.8, "you don't only perform better, that's where the real change starts to happen."], [172.8, 178.04, "I'm Raelle Graber, and I am so honored and excited to be here with you as a founding"], [178.04, 181.32, "Athletor Pro inside of Athletorship and MVP Accelerator."], [181.32, 185.88, "I can't wait to help you create sustainable wellness and unlock your next level."], [185.88, 186.6, "I'll see you inside."]], "pro_sagar": [[0.0, 10.6, "Hi, I'm Sagar Pandya."], [10.6, 12.84, "A few years ago, I was running"], [12.84, 15.88, "my IT and cybersecurity consulting company."], [15.88, 19.76, "Things were stable until suddenly they weren't."], [19.76, 23.36, "Overnight, every client conversation shifted."], [23.36, 27.56, "It went from how do we stay secure to,"], [27.56, 30.28, "what are we supposed to do with AI?"], [30.28, 34.14, "Internally, my team was feeling the weight too."], [34.14, 36.76, "Uncertainty, confusion."], [36.76, 38.44, "There was no roadmap,"], [38.44, 40.24, "no expert to lean on."], [40.24, 42.64, "But everyone kept looking at me,"], [42.64, 44.96, "hoping that I had the answers."], [44.96, 47.2, "That's when I realized something."], [47.2, 48.84, "I couldn't fake it."], [48.84, 53.04, "I couldn't lead from a place of control or ego."], [53.04, 57.28, "I had to shift from knowing to listening."], [57.28, 60.24, "From managing pressure to moving"], [60.24, 63.0, "through it with my team by my side."], [63.0, 66.24, "So I stopped trying to lead the conversation,"], [66.24, 69.8, "and instead started creating space for it."], [69.8, 72.16, "I brought my team together."], [72.16, 75.84, "We didn't talk tech, we talked mission."], [75.84, 78.2, "What's all of our role in this?"], [78.2, 80.0, "What do we believe in,"], [80.0, 82.2, "even if things get chaotic?"], [82.2, 84.84, "That was a start of real alignment,"], [85.28, 89.56, "and that clarity gave us permission to try,"], [89.56, 92.4, "to experiment, to ask."], [92.4, 94.64, "That's when agility showed up."], [94.64, 98.12, "Not in speed, but in shared momentum."], [98.12, 100.24, "So here's what I'll tell you."], [100.24, 103.68, "If you're leading a team through change right now,"], [103.68, 106.48, "you don't need to be the smartest voice in the room."], [106.48, 108.64, "You need to be the clearest."], [108.64, 113.04, "Alignment starts with pausing and asking"], [113.04, 116.0, "what matters to us in this moment."], [116.0, 119.04, "And agility follows when you give your team permission"], [119.04, 121.64, "to grow, not just perform."], [122.6, 124.68, "So here's your challenge."], [124.68, 127.8, "This week, take 15 minutes with your team."], [128.72, 132.08, "Don't talk metrics, but just ask one question."], [133.12, 135.92, "What's our mission right now in this season?"], [137.08, 138.24, "And then just listen."], [139.24, 144.24, "Because leadership in flow isn't about moving fast."], [144.68, 147.36, "It's about getting clear together."]], "pro_stephanie": [[0.0, 13.76, "Hi, I'm Stephanie Johnson, and if there's one thing I've learned over the years, it's"], [13.76, 14.76, "this."], [14.76, 18.72, "Leadership is forged in motion, often under pressure."], [18.72, 23.44, "A few years ago, I stepped into a new leadership role at a company in real trouble."], [23.44, 28.08, "Static revenue, unclear priorities, a team that was surviving instead of thriving."], [28.08, 33.84, "The instinct in moments like this is to take control, make big declarations, and move fast."], [33.84, 36.68, "But I didn't show up swinging a hammer of authority."], [36.68, 38.8, "I led with a different rhythm."], [38.8, 42.96, "Listen first, align fast, and adapt boldly."], [42.96, 48.1, "Listening first meant slowing down long enough to understand what wasn't being said."], [48.1, 52.32, "To hear the tension behind the silence, the exhaustion behind the surface, I met with"], [52.32, 57.72, "team members one-on-one, learning their stories, their frustrations, and their hopes."], [57.72, 61.1, "Playing fast meant finding the common thread of the chaos, a shared sense of purpose we"], [61.1, 63.24, "could all rally around."], [63.24, 65.56, "We don't have time for a drawn-out reset."], [65.56, 68.84, "We needed clarity, and we needed it quickly."], [68.84, 74.16, "Adapting boldly meant not being afraid to pivot, to experiment, to fail fast and learn"], [74.16, 75.16, "faster."], [75.16, 79.16, "I've never been afraid of change, and I'm not afraid of failure because both are essential"], [79.16, 80.82, "to transformation."], [80.82, 83.54, "That mindset became our way forward."], [83.54, 85.68, "Not perfect, but present."], [85.68, 87.48, "Not rigid, but rooted."], [87.48, 92.92, "And it's what allowed us to move from barely surviving to intentionally thriving."], [92.92, 97.32, "As we peeled back the layers, we discovered what truly motivated each person."], [97.32, 102.12, "Not just their job titles, but what is their story?"], [102.12, 103.56, "Who are their families?"], [103.56, 104.88, "What are their fears?"], [104.88, 105.88, "What are their dreams?"], [105.88, 110.22, "And in that messy human space, something clicked."], [110.22, 112.4, "We started flowing as a team."], [112.4, 116.28, "Not because we had all the answers, but because we had a shared alignment and trust."], [116.76, 119.32, "Here's where the real power showed up."], [119.32, 125.64, "I made the choice to bring my whole self to work every day, even on the tough days."], [125.64, 130.48, "I gave myself permission to lead with authenticity, and in doing so, I gave others permission"], [130.48, 132.04, "to do the same."], [132.04, 134.68, "And that's when the magic really, really started happening."], [134.68, 139.64, "Not performative magic, not perfection magic, just real."], [139.64, 142.64, "And in real is power."], [142.64, 144.96, "Here's what I've learned from Team Flow."], [144.96, 147.68, "Flow doesn't happen when everyone's doing the same thing."], [147.68, 152.2, "Flow happens when everyone is doing the right thing in harmony."], [152.2, 156.04, "Alignment isn't about forcing agreement, it's about creating clarity."], [156.04, 160.96, "Agility isn't about chaos, it's about responsiveness noted in shared purpose."], [160.96, 164.96, "But none of that is sustainable unless people feel safe to show up as they are."], [164.96, 173.48, "So many leaders think power comes from control, but real power, real power comes from authenticity."], [173.48, 177.84, "From owning who you are and creating space for others to do the same."], [177.84, 181.48, "That's what unlocks trust, that's what builds resilient teams, and that's what gets you"], [181.48, 183.8, "from resistance to flow."], [183.8, 185.12, "So here's my challenge to you."], [185.12, 191.2, "When pressure hits, and it will, don't tighten your grip, loosen it, pause, ask your team"], [191.2, 197.06, "about their why, lead with curiosity, not control, and instead of trying to direct every"], [197.06, 202.36, "single thing in every move, build alignment around the purpose, and let that alignment"], [202.44, 204.28, "be the fuel for agility."], [204.28, 209.24, "Show up as yourself every day, especially on the hard days, and be the kind of leader"], [209.24, 212.04, "who gives others the freedom to do the same."], [212.04, 216.64, "That is the heartbeat of high performing, human first teams."], [216.64, 222.6, "Team flow is not accidental, it's intentional, it's relational, and it's real, and it starts"], [222.6, 225.44, "with you leading from within."], [225.44, 229.88, "Let's change the way the world sees leadership, starting with how you see yourself."]], "pro_tracey": [[0.0, 14.92, "I will never forget this moment."], [14.92, 20.64, "A major outage had occurred for a technology company where I was responsible for all of"], [20.64, 21.92, "revenue."], [21.92, 28.48, "I was new to the company, and we had impacted some of the biggest companies on the planet"], [28.48, 33.2, "where they were not able to do business as promised."], [33.2, 35.04, "Everyone was scrambling."], [35.04, 37.2, "No one had a solution."], [37.2, 40.88, "And I was on vacation with my family."], [40.88, 43.16, "Here's what I learned about myself."], [43.16, 49.58, "When life gets difficult, it can be tempting to hide, to shrink, or even to just avoid"], [49.58, 52.36, "the situation, to delegate."], [52.36, 54.12, "That's not what I did."], [54.12, 56.76, "And that's not what you should do either."], [56.76, 61.38, "This crisis was one of those moments where showing up really mattered."], [61.38, 67.28, "And so I did, from a hotel room, on calls I didn't plan to take, while my family waited"], [67.28, 70.36, "and eventually had to go on without me."], [70.36, 73.56, "Not because I had the answers, I really didn't."], [73.56, 78.96, "I found myself hosting hourly calls with my teams, trying to create some kind of rhythm"], [78.96, 82.44, "and order at a time of great uncertainty."], [82.44, 91.36, "Our customers were rightfully upset, and our teams were so nervous and needed help."], [91.36, 95.64, "Everyone needs to know at these times that someone is paying attention."], [95.64, 99.96, "That we were going to keep moving forward one step at a time, even if we didn't have"], [99.96, 101.76, "it all figured out."], [101.76, 106.9, "We worked around the clock, and eventually everything was back to normal."], [106.9, 108.56, "We got through it."], [108.56, 113.18, "What I found so interesting about the outcome of the entire event is that we built stronger"], [113.18, 119.24, "relationships with our clients than ever before as a result of the incident."], [119.24, 123.72, "We earned their trust by showing up when it mattered most."], [123.72, 130.36, "And here's the lesson I want you to take with you as you embark on your 90-day journey."], [130.36, 135.62, "In life, things will go wrong, and when they do, people will want answers."], [135.62, 142.3, "But if you can't give concrete answers, they expect you at a minimum to remain accessible"], [142.3, 144.5, "and visible."], [144.5, 147.82, "Consistent communication will never be more important."], [147.82, 153.1, "And at the end of the day, most people understand that issues will come up."], [153.1, 157.38, "Every person and every company will have issues at some point."], [157.38, 163.74, "How you show up in those times makes all the difference, and it's what defines you as a"], [163.74, 165.06, "leader."], [165.06, 172.7, "Being agile and resilient will never be more important when you're facing big challenges."], [172.7, 175.84, "So here's my question for you."], [175.84, 178.86, "How will you show up in times of uncertainty?"]], "welcome": [[0.36, 2.2, "Welcome to the arena."], [2.2, 4.44, "This isn't just a platform,"], [4.44, 8.24, "it's your starting line for a new kind of leadership,"], [8.24, 11.48, "built from within, conditioned to win."], [11.48, 14.16, "Here, you're not just joining a course,"], [14.16, 18.96, "you're stepping into a system, a movement, a mindset."], [18.96, 22.66, "Inside this space, you'll find the M.V.P. Accelerator."], [23.58, 25.52, "Our foundational experience,"], [25.52, 28.08, "alongside other high-impact programs,"], [28.08, 30.0, "will continue to release."], [30.0, 34.44, "But first, let's talk about who you are here."], [34.44, 36.88, "You're not here because of a title."], [36.88, 40.12, "You're not here because of a position."], [40.12, 43.52, "You're here because you believe there's more,"], [43.52, 46.84, "and you're willing to do the work to unlock it."], [46.84, 49.08, "You're not simply a participant."], [49.08, 51.48, "We call you an Athleader."], [51.48, 55.16, "An Athleader is someone who leads like the elite perform,"], [55.16, 57.36, "resilient under pressure,"], [57.4, 62.0, "clear in purpose, built for the long game."], [62.0, 65.22, "And for those of you who are managers in your role,"], [65.22, 68.6, "you're not just a bystander supporting your participant."], [68.6, 72.56, "You're a Player-Coach, responsible for leading yourself"], [72.56, 75.48, "and influencing those around you."], [75.48, 78.82, "This is your locker room moment."], [78.82, 83.34, "Well, you're prepared, reflect, and commit."], [83.34, 85.32, "Because leadership isn't a position,"], [85.36, 88.32, "it's a daily practice."], [88.32, 91.08, "Why is the lion a symbol for leadership?"], [91.08, 94.04, "Not because it's the biggest or the strongest,"], [94.04, 96.44, "but because of its mindset."], [96.44, 101.24, "That's what we're building here, mental muscle memory."], [101.24, 103.56, "We condition across A.R.A.W."], [103.56, 105.48, "It's what we call the Core 4."], [105.48, 109.72, "It's agility, resilience, alignment, and wellbeing,"], [109.72, 113.22, "grounded in neuroscience and performance psychology"], [113.22, 117.3, "to shape identity that endures under pressure."], [117.3, 120.62, "You will track your momentum, know your metrics."], [120.62, 122.94, "You'll see how far you've come"], [122.94, 125.14, "and where you can still grow."], [125.14, 128.22, "Know this, you're not alone."], [128.22, 129.82, "You're a part of a team."], [129.82, 131.86, "You'll be connected to your squad,"], [131.86, 135.78, "extended M.V.P. community, and accountability partner."], [135.78, 138.54, "You will learn from other Athleader pros,"], [138.54, 142.18, "share your voice, and celebrate progress together."], [142.18, 143.54, "So what's next?"], [143.54, 146.98, "Go through your step-by-step actions to get started."], [146.98, 150.48, "Lace up, lock in, let's go."], [150.48, 152.44, "This is your arena."], [152.44, 154.4, "This is your time."], [154.4, 156.34, "Let's win from within."]]};
